import argparse
from operations import Calculator

def main():
    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument("--op", choices=[
        'add', 'subtract', 'multiply', 'divide', 'power', 'modulo', 
        'memory_store', 'memory_recall', 'memory_clear', 
        'get_history', 'clear_history', 'evaluate'
    ], required=True, help="Operation to perform")

    # Use nargs='*' to allow flexible number of arguments based on operation
    parser.add_argument("args", nargs='*', help="Arguments for the operation")

    args = parser.parse_args()
    calc = Calculator()

    try:
        operation = getattr(calc, args.op)

        # Determine how to call the function based on the operation
        if args.op in ['add', 'subtract', 'multiply', 'divide', 'power', 'modulo']:
            if len(args.args) < 2:
                print(f"Error: {args.op} requires 2 arguments")
                return
            result = operation(float(args.args[0]), float(args.args[1]))
            print(f"Result: {result}")

        elif args.op == 'memory_store':
            if not args.args:
                print("Error: memory_store requires 1 argument")
                return
            operation(float(args.args[0]))
            print("Value stored in memory.")

        elif args.op == 'evaluate':
            if not args.args:
                print("Error: evaluate requires an expression string")
                return
            # Join arguments in case the expression contains spaces
            expr = " ".join(args.args)
            result = operation(expr)
            print(f"Result: {result}")

        elif args.op in ['get_history', 'clear_history', 'memory_recall', 'memory_clear']:
            result = operation()
            if args.op == 'get_history':
                print(f"History: {result}")
            elif args.op == 'memory_recall':
                print(f"Memory: {result}")
            else:
                print(f"{args.op.replace('_', ' ').capitalize()} complete.")

        if args.op not in ['get_history', 'clear_history']:
            print(f"History Length: {len(calc.get_history())}")

    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

