import argparse
from operations import Calculator

def main() -> None:
    """
    Main entry point for the CLI calculator.
    Processes command line arguments, performs calculations, and displays history.
    """
    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument("--op", choices=[
        'add', 'subtract', 'multiply', 'divide', 'power', 'modulo', 
        'memory_store', 'memory_recall', 'memory_clear', 'evaluate', 
        'get_history', 'clear_history'
    ], required=True)
    parser.add_argument("a", type=float, nargs="?", help="First operand (or value for memory_store)")
    parser.add_argument("b", type=float, nargs="?", help="Second operand")
    parser.add_argument("--expr", type=str, help="Expression string for evaluate")

    args = parser.parse_args()
    calc = Calculator()

    try:
        if args.op == 'evaluate':
            if not args.expr:
                print("Error: --expr is required for evaluate operation")
                return
            result = calc.evaluate(args.expr)
            print(f"Result: {result}")
        elif args.op == 'memory_store':
            if args.a is None:
                print("Error: First operand required for memory_store")
                return
            calc.memory_store(args.a)
            print("Value stored in memory.")
        elif args.op in ['memory_recall', 'memory_clear', 'get_history', 'clear_history']:
            func = getattr(calc, args.op)
            result = func()
            if result is not None:
                print(f"Result: {result}")
            else:
                print("Operation successful.")
        else:
            # Binary operations
            if args.a is None or args.b is None:
                print("Error: Two operands required for this operation")
                return
            func = getattr(calc, args.op)
            result = func(args.a, args.b)
            print(f"Result: {result}")

        print(f"History: {calc.get_history()}")
    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

